import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function ManageTeachers() {
  const [teachers, setTeachers] = useState([]);
  const [formData, setFormData] = useState({
    name: '', subject: '', qualifications: '', email: '', phone_number: '', address: '', password: 'TC@123'
  });

  const fetchTeachers = () => {
    axios.get('http://localhost:8081/api/view-teachers')
      .then(res => setTeachers(res.data))
      .catch(err => console.error(err));
  };

  useEffect(() => { fetchTeachers(); }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    axios.post('http://localhost:8081/api/add-teacher', formData)
      .then(res => {
        if(res.data.status === "Success") {
            fetchTeachers(); 
            setFormData({ name: '', subject: '', qualifications: '', email: '', phone_number: '', address: '', password: 'TC@123' });
            alert("✅ Lecturer added successfully!");
        } else {
            alert("❌ Failed to add lecturer.");
        }
      });
  };

  return (
    <div style={{ padding: '30px', backgroundColor: '#f8fafc', minHeight: '100vh' }}>
      <h2 style={{ color: '#15803d', marginBottom: '20px' }}>Manage Lecturers</h2>
      
      {/* 🟢 Add New Lecturer Form */}
      <div style={{ backgroundColor: 'white', padding: '25px', borderRadius: '12px', boxShadow: '0 4px 15px rgba(0,0,0,0.05)', marginBottom: '30px' }}>
        <h3 style={{ marginTop: 0, color: '#334155', borderBottom: '2px solid #f1f5f9', paddingBottom: '10px' }}>Add New Lecturer</h3>
        <form onSubmit={handleSubmit} style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '15px', marginTop: '20px' }}>
          
          <input type="text" placeholder="Full Name" value={formData.name} onChange={(e) => setFormData({...formData, name: e.target.value})} required style={inputStyle} />
          <input type="text" placeholder="Teaching Subject" value={formData.subject} onChange={(e) => setFormData({...formData, subject: e.target.value})} required style={inputStyle} />
          <input type="text" placeholder="Qualifications (e.g. B.Sc, M.Ed)" value={formData.qualifications} onChange={(e) => setFormData({...formData, qualifications: e.target.value})} style={inputStyle} />
          <input type="email" placeholder="Email Address" value={formData.email} onChange={(e) => setFormData({...formData, email: e.target.value})} style={inputStyle} />
          <input type="text" placeholder="Contact Number" value={formData.phone_number} onChange={(e) => setFormData({...formData, phone_number: e.target.value})} style={inputStyle} />
          <input type="text" placeholder="Residence Address" value={formData.address} onChange={(e) => setFormData({...formData, address: e.target.value})} style={inputStyle} />
          
          <div style={{ gridColumn: 'span 2', backgroundColor: '#f0fdf4', padding: '10px', borderRadius: '8px', border: '1px dashed #22c55e', fontSize: '13px', color: '#15803d' }}>
            <strong>Note:</strong> The default password for this lecturer will be set to <b>TC@123</b>. They can change it after logging in.
          </div>

          <button type="submit" style={{ gridColumn: 'span 2', padding: '14px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '15px' }}>
            + Register Lecturer
          </button>
        </form>
      </div>

      {/* 🟢 View Lecturers Table */}
      <div style={{ backgroundColor: 'white', borderRadius: '12px', boxShadow: '0 4px 15px rgba(0,0,0,0.05)', overflow: 'auto' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left', minWidth: '900px' }}>
          <thead style={{ backgroundColor: '#15803d', color: 'white' }}>
            <tr>
              <th style={thStyle}>Full Name</th><th style={thStyle}>Subject</th><th style={thStyle}>Qualifications</th>
              <th style={thStyle}>Email</th><th style={thStyle}>Phone</th><th style={thStyle}>Address</th>
            </tr>
          </thead>
          <tbody>
            {teachers.length > 0 ? teachers.map((teacher) => (
              <tr key={teacher.id} style={{ borderBottom: '1px solid #f1f5f9' }}>
                <td style={tdStyle}><b>{teacher.name}</b></td><td style={tdStyle}>{teacher.subject}</td>
                <td style={tdStyle}>{teacher.qualifications || '-'}</td><td style={tdStyle}>{teacher.email || '-'}</td>
                <td style={tdStyle}>{teacher.phone_number || '-'}</td><td style={tdStyle}>{teacher.address || '-'}</td>
              </tr>
            )) : (
              <tr><td colSpan="6" style={{ padding: '20px', textAlign: 'center', color: '#ef4444' }}>No lecturers found.</td></tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

const inputStyle = { padding: '12px', border: '1px solid #cbd5e1', borderRadius: '8px', outline: 'none', width: '100%', boxSizing: 'border-box' };
const thStyle = { padding: '15px', fontSize: '14px', whiteSpace: 'nowrap' };
const tdStyle = { padding: '15px', fontSize: '14px', color: '#475569' };
